import{_ as t,a0 as l,w as o,s as d,ao as h,I as p,x as a,a1 as n,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"如何用樹莓派控制 GOIO 引腳並操作繼電器 | LCTT x X-CMD","titleTemplate":false,"description":"如何用樹莓派控制 GOIO 引腳並操作繼電器 | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何用樹莓派控制 GOIO 引腳並操作繼電器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何用樹莓派控制 GOIO 引腳並操作繼電器 | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170317 How to control GPIO pins and operate relays with the Raspberry Pi","title":"如何用樹莓派控制 GOIO 引腳並操作繼電器","tag":"201706","desc":""},"relativePath":"201706/20170317 How to control GPIO pins and operate relays with the Raspberry Pi.md","filePath":"[post].md"}'),c={name:"201706/20170317 How to control GPIO pins and operate relays with the Raspberry Pi.md"};function r(g,s,u,k,b,f){const i=l("Link");return o(),d("div",null,[s[13]||(s[13]=h(`<h1 id="如何用樹莓派控制-goio-引腳並操作繼電器" tabindex="-1">如何用樹莓派控制 GOIO 引腳並操作繼電器 <a class="header-anchor" href="#如何用樹莓派控制-goio-引腳並操作繼電器" aria-label="Permalink to “如何用樹莓派控制 GOIO 引腳並操作繼電器”">​</a></h1><blockquote><p>學習如何用 PHP 和温度傳感器實現樹莓派控制 GPIO 並操作繼電器</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/raspberry_pi_day_lead_0.jpeg?itok=lCxmviRD" alt="How to control GPIO pins and operate relays with the Raspberry Pi" title="How to control GPIO pins and operate relays with the Raspberry Pi"></p><p>你是否曾經想知道怎樣使用手機或者電腦在任何地方控制你的風扇和燈等一些家用電器？</p><p>我現在想控制我的聖誕彩燈，是使用手機呢，還是使用平板電腦呢，或者是使用筆記本電腦呢？都不是，而是僅僅使用一個樹莓派。讓我來告訴你如何使用 PHP 和温度傳感器實現樹莓派控制 GPIO 引腳並操作繼電器。我使用 AJAX 把它們整合在了一起。</p><h3 id="硬件要求" tabindex="-1">硬件要求： <a class="header-anchor" href="#硬件要求" aria-label="Permalink to “硬件要求：”">​</a></h3><ul><li>樹莓派</li><li>安裝有 Raspbian 系統的 SD 卡（任何一張 SD 卡都可以，但是我更偏向使用大小為 32GB 等級為 class 10 的 SD 卡）</li><li>電源適配器</li><li>跳線（母對母跳線和公轉母跳線）</li><li>繼電器板（我使用一個用於 12V 繼電器的繼電器板）</li><li>DS18B20 温度傳感器</li><li>樹莓派的 Wi-Fi 適配器</li><li>路由器（為了訪問互聯網，你需要有一個擁有端口轉發的路由器）</li><li>10KΩ 的電阻</li></ul><h3 id="軟件要求" tabindex="-1">軟件要求： <a class="header-anchor" href="#軟件要求" aria-label="Permalink to “軟件要求：”">​</a></h3><ul><li>下載並安裝 Raspbian 系統到你的 SD 卡</li><li>有效的互聯網連接</li><li>Apache web 服務器</li><li>PHP</li><li>WiringPi</li><li>基於 Mac 或者 Windows 的 SSH 客户端</li></ul><h3 id="一般的配置和設置" tabindex="-1">一般的配置和設置 <a class="header-anchor" href="#一般的配置和設置" aria-label="Permalink to “一般的配置和設置”">​</a></h3><p>1、 插入 SD 卡到樹莓派，然後使用以太網網線將它連接到路由器；</p><p>2、 連接 WiFi 適配器；</p><p>3、 使用 SSH 方式登錄到樹莓派，然後使用下面的命令編輯 <code>interfaces</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano /etc/network/interfaces</span></span></code></pre></div><p>這個命令會用一個叫做 <code>nano</code> 的編輯器打開這個文件。它是一個非常簡單又易於使用的文本編輯器。如果你不熟悉基 Linux 的操作系統，可以使用鍵盤上的方向鍵來操作。</p><p>用 <code>nano</code> 打開這個文件後，你會看到這樣一個界面：</p><p><img src="https://opensource.com/sites/default/files/putty_0.png" alt="File editor nano" title="File editor nano"></p><p>4、要配置你的無線網絡，按照下面所示修改這個文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iface lo inet loopback</span></span>
<span class="line"><span>iface eth0 inet dhcp</span></span>
<span class="line"><span>allow-hotplug wlan0</span></span>
<span class="line"><span>auto wlan0</span></span>
<span class="line"><span>iface wlan0 inet dhcp</span></span>
<span class="line"><span>   wpa-ssid &quot;Your Network SSID&quot;</span></span>
<span class="line"><span>   wpa-psk &quot;Your Password&quot;</span></span></code></pre></div><p>5、 按 <code>CTRL+O</code> 保存，然後按 <code>CTRL+X</code> 退出編輯器。</p><p>到目前為止，一切都已經配置完成，接下來你需要做的就是使用命令重新加載網絡：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo service networking reload</span></span></code></pre></div><p>（警告：如果你是使用遠程連接的方式連接的樹莓派，連接將會中斷。)</p><h3 id="軟件配置" tabindex="-1">軟件配置 <a class="header-anchor" href="#軟件配置" aria-label="Permalink to “軟件配置”">​</a></h3><h4 id="安裝-apache-web-服務器" tabindex="-1">安裝 Apache web 服務器 <a class="header-anchor" href="#安裝-apache-web-服務器" aria-label="Permalink to “安裝 Apache web 服務器”">​</a></h4><p>Apache 是一個受歡迎的服務器應用，你可以在樹莓派安裝這個程序讓它提供網頁服務。Apache 原本就可以通過 HTTP 方式提供 HTML 文件服務，添加其他模組後，Apache 還可以使用像 PHP 這樣的腳本語言來提供動態網頁的服務。</p><p>可以在命令列輸入下面命令安裝 Apache：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install apache2 -y</span></span></code></pre></div><p>安裝完成後，可以在瀏覽器地址欄輸入樹莓派的 IP 地址來測試 web 服務器。如果你可以獲得下面圖片的內容，説明你已經成功地安裝並設置好了你的服務器。</p><p><img src="https://opensource.com/sites/default/files/itworks.png" alt="Successful server setup" title="Successful server setup"></p><p>要改變這個默認的頁面和添加你自己的 html 文件，進入 <code>var/www/html</code> 目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /var/www/html</span></span></code></pre></div><p>添加一些文件來測試是否成功。</p><h4 id="安裝-php" tabindex="-1">安裝 PHP <a class="header-anchor" href="#安裝-php" aria-label="Permalink to “安裝 PHP”">​</a></h4><p>PHP 是一個預處理器，這意味着它是當服務器收到網頁請求時才會運行的一段代碼。它開始運行，處理網頁上需要被顯示的內容，然後把網頁發送給瀏覽器。不像靜態的 HTML，PHP 在不同的環境下可以顯示不同的內容。其他的語言也可以做到這一點，但是由於 WordPress 是用 PHP 編寫的，有些時候你需要使用它。PHP 是 web 上一種非常受歡迎的語言，像 Facebok 和 Wikipeadia 這樣的大型項目都是用 PHP 編寫的。</p><p>使用下面的命令安裝 PHP 和 Apache 軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install php5 libapache2-mod-php5 -y</span></span></code></pre></div><h4 id="測試-php" tabindex="-1">測試 PHP <a class="header-anchor" href="#測試-php" aria-label="Permalink to “測試 PHP”">​</a></h4><p>創建文件 <code>index.php</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano index.php</span></span></code></pre></div><p>在裏面寫入一些 PHP 內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?php echo &quot;hello world&quot;; ?&gt;</span></span></code></pre></div><p>保存文件，接下來刪除 <code>index.html</code>，因為它比 <code>index.php</code> 的優先級更高：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rm index.html</span></span></code></pre></div><p>刷新你的瀏覽器，你會看到 “hello world”。這並不是動態的，但是它仍然由 PHP 提供服務。如果你在上面看到提原始的 PHP 文件而不是“hello world”，重新加載和重啓 Apahce（LCTT 譯註，重啓即可）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo /etc/init.d/apache2 reload</span></span>
<span class="line"><span>sudo /etc/init.d/apache2 restart</span></span></code></pre></div><h4 id="安裝-wiringpi" tabindex="-1">安裝 WiringPi <a class="header-anchor" href="#安裝-wiringpi" aria-label="Permalink to “安裝 WiringPi”">​</a></h4><p>為了可以對代碼的更改進行跟蹤，WiringPi 的維護採用 git。但假如你因為某些原因而沒法使用 git，還有一種可以替代的方案。（通常你的防火牆會把你隔離開來，所以請先檢查一下你的防火牆的設置情況！）</p><p>如果你還沒有安裝 git，那麼在 Debian 及其衍生版本中（比如 Raspbian），你可以這樣安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install git-core</span></span></code></pre></div><p>若是你遇到了一些錯誤，請確保你的樹莓派是最新版本的 Raspbian 系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get update sudo apt-get upgrade</span></span></code></pre></div><p>使用 git 獲取最 WiringPi：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo git clone git://git.drogon.net/wiringPi</span></span></code></pre></div><p>如果你之前已經使用過 clone 操作，那麼可以使用下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd wiringPi &amp;&amp; git pull origin</span></span></code></pre></div><p>這個命令會將會獲取更新的版本，你然後可以重新運行下面的構建腳本。</p><p>有一個新的簡化的腳本來構建和安裝:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd wiringPi &amp;&amp; ./build</span></span></code></pre></div><p>這個新的構建腳本將會為你完成編譯和安裝 WiringPi。它曾一度需要使用 <code>sudo</code> 命令，所以在運行這它之前你可能需要檢查一下這個腳本。</p><h4 id="測試-wiringpi" tabindex="-1">測試 WiringPi <a class="header-anchor" href="#測試-wiringpi" aria-label="Permalink to “測試 WiringPi”">​</a></h4><p>運行 <code>gpio</code> 命令來檢查安裝成功與否:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gpio -v gpio readall</span></span></code></pre></div><p>這將給你一些信心，軟件運行良好。</p><h4 id="連接-ds18b20-傳感器到樹莓派" tabindex="-1">連接 DS18B20 傳感器到樹莓派 <a class="header-anchor" href="#連接-ds18b20-傳感器到樹莓派" aria-label="Permalink to “連接 DS18B20 傳感器到樹莓派”">​</a></h4><ul><li>傳感器上的黑線用於 GND。</li><li>紅線用於 VCC。</li><li>黃線是 GPIO 線。</li></ul><p><img src="https://opensource.com/sites/default/files/gpio_0.png" alt="GPIO image" title="GPIO image"></p><p>連線：</p><ul><li>VCC 連接 3V 的 1 號引腳。</li><li>GPIO 線連接 7 號引腳（GPIO4）。</li><li>地線連接 GND 的 9 號引腳。</li></ul><h4 id="軟件配置-1" tabindex="-1">軟件配置 <a class="header-anchor" href="#軟件配置-1" aria-label="Permalink to “軟件配置”">​</a></h4><p>為了用 PHP 使用 DS18B20 温度傳感器模組，你需要執行下面的命令來激活用於樹莓派上 GPIO 引腳和 DS18B20 的內核模組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo modprobe w1-gpio</span></span>
<span class="line"><span>sudo modprobe w1-therm</span></span></code></pre></div><p>你不想每次 Raspberry 重啓後都手動執行上述命令，所以你想每次開機能自動啓動這些模組。可以在文件 <code>/etc/modules</code> 中添加下面的命令列來做到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano /etc/modules/</span></span></code></pre></div><p>添加下面的命令列到它裏面:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>w1-gpio</span></span>
<span class="line"><span>w1-therm</span></span></code></pre></div><p>為了測試，輸入:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /sys/bus/w1/devices/</span></span></code></pre></div><p>現在輸入 <code>ls</code>。</p><p>你會看到你的設備信息。在設備驅動程序中，你的 DS18B20 傳感器應該作為一串字母和數字被列出。在本例中，設備被記錄為 <code>28-000005e2fdc3</code>。然後你需要使用 <code>cd</code> 命令來訪問傳感器，用你自己的序列號替代我的： <code>cd 28-000005e2fdc3</code>。</p><p>DS18B20 會週期性的將數據寫入文件 <code>w1_slave</code>，所以你只需要使用命令 <code>cat</code>來讀出數據： <code>cat w1_slave</code>。</p><p>這會生成下面的兩行文本，輸出中 <code>t=</code> 表示攝氏單位的温度。在前兩位數後面加上一個小數點(例如，我收到的温度讀數是 30.125 攝氏度)。</p><h3 id="連接繼電器" tabindex="-1">連接繼電器 <a class="header-anchor" href="#連接繼電器" aria-label="Permalink to “連接繼電器”">​</a></h3><p>1、 取兩根跳線，把其中一根連接到樹莓派上的 GPIO24（18 號引腳），另一根連接 GND 引腳。你可以參考下面這張圖。</p><p>2、 現在將跳線的另一端連接到繼電器板。GND 連接到繼電器上的 GND，GPIO 輸出線連接到繼電器的通道引腳號，這取決於你正使用的繼電器型號。記住，將樹莓派上的 GND 與繼電器上的 GND 連接連接起來，樹莓派上的 GPIO 輸出連接繼電器上的輸入引腳。</p><p><img src="https://opensource.com/sites/default/files/headers.png" alt="Headers" title="Headers"></p><p>注意！將繼電器連接樹莓派的時候小心一些，因為它可能會導致電流回流，這會造成短路。</p><p>3、 現在將電源連接繼電器，可以使用 12V 的電源適配器，也可以將 VCC 引腳連接到什麼破上的 3.3V 或 5.5V 引腳。</p><h3 id="使用-php-控制繼電器" tabindex="-1">使用 PHP 控制繼電器 <a class="header-anchor" href="#使用-php-控制繼電器" aria-label="Permalink to “使用 PHP 控制繼電器”">​</a></h3><p>讓我們先寫一個藉助於 WiringPi 軟件用來控制 Paspberry Pi 上 GPIO 引腳的 PHP 腳本。</p><p>1、在 Apache 服務器的網站根目錄下創建一個文件，使用下面命令切換到該目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /var/www/html</span></span></code></pre></div><p>2、 新建一個叫 <code>Home</code> 的文件夾：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkdir Home</span></span></code></pre></div><p>3、 新建一個叫 <code>on.php</code>的腳本</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano on.php</span></span></code></pre></div><p>4、 在腳本中加入下面的代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?php</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        system(&quot;gpio-g mode 24 out&quot;);</span></span>
<span class="line"><span>        system(&quot;gpio-g write 24 1&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>?&gt;</span></span></code></pre></div><p>5、 使用 <code>CTRL+O</code> 保存文件，<code>CTRL+X</code> 退出。</p><p>上面的代碼中，你在第一行使用命令將 24 號 GPIO引腳設置為 output 模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>system(&quot;gpio-g mode 24 out&quot;) ;</span></span></code></pre></div><p>在第二行，你使用 <code>1</code> 將 24 號引腳 GPIO 打開，在二進制中&quot;1&quot;表示打開，&quot;0&quot;表示關閉。</p><p>6、 為了關閉繼電器，可以創建另外一個 <code>off.php</code> 文件，並用 <code>0</code> 替換 <code>1</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?php</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        system(&quot; gpio-g mode 24 out &quot;);</span></span>
<span class="line"><span>        system(&quot; gpio-g write 24 1 &quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>?&gt;</span></span></code></pre></div><p>7、 如果你已經將繼電器連接了樹莓派，可以在瀏覽器中輸入你的樹莓派的 IP 地址，並在後面加上目錄名和文件名來進行訪問：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://{IPADDRESS}/home/on.php</span></span></code></pre></div><p>這將會打開繼電器。</p><p>8、 要關閉它，可以訪問叫 <code>off.php</code> 的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://{IPADDRESS}/home/off.php</span></span></code></pre></div><p>現在你需要能夠在一個單獨的頁面來控制這兩樣事情，而不用單獨的刷新或者訪問這兩個頁面。你可以使用 AJAX 來完成。</p><p>9、 新建一個 HTML 文件，並在其中加入下面代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[html + php + ajax codeblock]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;script src=&quot;https://ajax.googleapis.com/ajax/libs/jquery/1.11.3/jquery.min.js&quot;&gt;&lt;/script&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;script type=&quot;text/javascript&quot;&gt;// &lt;![CDATA[</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$(document).ready(function() {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$(&#39;#on&#39;).click(function(){</span></span>
<span class="line"><span></span></span>
<span class="line"><span>var a= new XMLHttpRequest();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>a.open(&quot;GET&quot;, &quot;on.php&quot;); a.onreadystatechange=function(){</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if(a.readyState==4){ if(a.status ==200){</span></span>
<span class="line"><span></span></span>
<span class="line"><span> } else alert (&quot;http error&quot;); } }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>a.send();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$(document).ready(function()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{ $(&#39;#Off&#39;).click(function(){</span></span>
<span class="line"><span></span></span>
<span class="line"><span>var a= new XMLHttpRequest();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>a.open(&quot;GET&quot;, &quot;off.php&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>a.onreadystatechange=function(){</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if(a.readyState==4){</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if(a.status ==200){</span></span>
<span class="line"><span></span></span>
<span class="line"><span> } else alert (&quot;http error&quot;); } }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>a.send();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;/script&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;button id=&quot;on&quot; type=&quot;button&quot;\`\`Switch Lights On &lt;/button&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;button id=&quot;off&quot; type=&quot;button&quot;\`\`Switch Lights Off &lt;/button&gt;</span></span></code></pre></div><p>10、 保存文件，進入你的 web 瀏覽器目錄，然後打開那個網頁。你會看到兩個按鈕，它們可以打開和關閉燈泡。基於同樣的想法，你還可以使用 bootstrap 和 CSS 來創建一個更加漂亮的 web 界面。</p><h3 id="在這個網頁上觀察温度" tabindex="-1">在這個網頁上觀察温度 <a class="header-anchor" href="#在這個網頁上觀察温度" aria-label="Permalink to “在這個網頁上觀察温度”">​</a></h3><p>1、 新建一個 <code>temperature.php</code> 的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano temperature.php</span></span></code></pre></div><p>2、 在文件中加入下面的代碼，用你自己的設備 ID 替換 <code>10-000802292522</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?php</span></span>
<span class="line"><span>//File to read</span></span>
<span class="line"><span>$file = &#39;/sys/devices/w1_bus_master1/10-000802292522/w1_slave&#39;;</span></span>
<span class="line"><span>//Read the file line by line</span></span>
<span class="line"><span>$lines = file($file);</span></span>
<span class="line"><span>//Get the temp from second line</span></span>
<span class="line"><span>$temp = explode(&#39;=&#39;, $lines[1]);</span></span>
<span class="line"><span>//Setup some nice formatting (i.e., 21,3)</span></span>
<span class="line"><span>$temp = number_format($temp[1] / 1000, 1, &#39;,&#39;, &#39;&#39;);</span></span>
<span class="line"><span>//And echo that temp</span></span>
<span class="line"><span>echo $temp . &quot; °C&quot;;</span></span>
<span class="line"><span>?&gt;</span></span></code></pre></div><p>3、 打開你剛剛創建的 HTML 文件，並創建一個新的帶有 <code>id</code> 為 “screen” 的 <code>&lt;div&gt;</code>標籤</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;div id=&quot;screen&quot;&gt;&lt;/div&gt;</span></span></code></pre></div><p>4、 在這個標籤後或者這個文檔的尾部下面的代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;script&gt;</span></span>
<span class="line"><span>$(document).ready(function(){</span></span>
<span class="line"><span>setInterval(function(){</span></span>
<span class="line"><span>$(&quot;#screen&quot;).load(&#39;temperature.php&#39;)</span></span>
<span class="line"><span>}, 1000);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span>&lt;/script&gt;</span></span></code></pre></div><p>其中，<code>#screen</code> 是標籤 <code>&lt;div&gt;</code> 的 <code>id</code> ，你想在它裏面顯示温度。它會每隔 1000 毫秒加載一次 <code>temperature.php</code> 文件。</p><p>我使用了 bootstrap 框架來製作一個漂亮的面板來顯示温度，你還可以加入多個圖標和圖形讓網頁更有吸引力。</p><p>這只是一個控制繼電器板並顯示温度的基礎的系統，你可以通過創建基於定時和從恆温器讀數等基於事件觸發來進一步地對系統進行開發。</p><p>（ 題圖：opensource.com）</p><hr><p>作者簡介：</p><p>Abdul Hannan Mustajab: 我 17 歲，生活在印度。我正在追求科學，數學和計算機科學方面的教育。我在 spunkytechnology.com 上發表關於我的項目的Blog。我一直在對使用不同的微控制器和電路板的基於物聯網的 AI 進行研究。</p>`,129)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),n(i,{href:"https://opensource.com/article/17/3/operate-relays-control-gpio-pins-raspberry-pi"},{default:e(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/17/3/operate-relays-control-gpio-pins-raspberry-pi",-1)])]),_:1})]),p("p",null,[s[5]||(s[5]=a("作者：",-1)),n(i,{href:"https://opensource.com/users/mustajabhannan"},{default:e(()=>[...s[2]||(s[2]=[a("Abdul Hannan Mustajab",-1)])]),_:1}),s[6]||(s[6]=a(" 譯者：",-1)),n(i,{href:"https://github.com/zhousiyu325"},{default:e(()=>[...s[3]||(s[3]=[a("zhousiyu325",-1)])]),_:1}),s[7]||(s[7]=a(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[10]||(s[10]=a("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:e(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const C=t(c,[["render",r]]);export{P as __pageData,C as default};
